    \end{align*}

For (2), a tight enough upper bound is:\begin{align*}
        \sum_{h=1}^{H} \|\mu^\pi_{M,h} - \mu^\pi_{\tM,h}\|_\TV \leq & \sum_{h=1}^{H} \EE_{\pi,M}[\sum_{\ph=1}^{h-1} (1+L_T)^{h-\ph-1} \|\mP_{T,\ph}(\cdot|s_\ph,a_\ph,\mu^\pi_{M,\ph}) - \mP_{\tT,\ph}(\cdot|s_\ph,a_\ph,\mu^\pi_{M,\ph})\|_\TV]\\
        = & \sum_{h=1}^{H} \frac{(1 + L_T)^{H-h} - 1}{L_T}\EE_{\pi,M}[\|\mP_{T,h}(\cdot|s_h,a_h,\mu^\pi_{M,h}) - \mP_{\tT,h}(\cdot|s_h,a_h,\mu^\pi_{M,h})\|_\TV]
